import React, { useState } from 'react';

function LogDetailModal({ log, onClose, onDelete }) {
  const [deleting, setDeleting] = useState(false);

  if (!log) return null;

  const handleDelete = async () => {
    if (!onDelete) return;
    const ok = window.confirm(`이 로그(ID: ${log.id})를 삭제할까요?`);
    if (!ok) return;

    try {
      setDeleting(true);
      await onDelete(log);
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="modal-backdrop">
      <div className="modal">
        <h2>로그 상세 (ID: {log.id})</h2>

        <div className="modal-content">
          <p><strong>수집 시각:</strong> {log.collectedAt}</p>
          <p><strong>이벤트 타입:</strong> {log.eventType}</p>
          <p><strong>파일 경로:</strong> {log.path}</p>
          <p><strong>파일 존재 여부:</strong> {log.exists ? '존재' : '삭제됨'}</p>
          <p><strong>파일 크기:</strong> {log.size} bytes</p>
          <p><strong>마지막 수정:</strong> {log.lastModifiedTime}</p>
          <p><strong>해시:</strong> {log.hash || '(없음)'}</p>
          <p><strong>엔트로피:</strong> {log.entropy ?? '(없음)'}</p>

          <hr />

          <p><strong>AI 라벨:</strong> {log.aiLabel || '(없음)'}</p>
          <p><strong>AI 점수:</strong> {log.aiScore ?? '(없음)'}</p>
          <p><strong>AI 상세:</strong></p>
          <pre style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
            {log.aiDetail || '(상세 내용 없음)'}
          </pre>
        </div>

        <div className="modal-actions" style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
          {onDelete && (
            <button className="btn btn-danger" onClick={handleDelete} disabled={deleting}>
              {deleting ? '삭제 중...' : '삭제'}
            </button>
          )}
          <button className="btn" onClick={onClose} disabled={deleting}>
            닫기
          </button>
        </div>
      </div>
    </div>
  );
}

export default LogDetailModal;
